package com.example.medilembrete;
import android.app.Activity;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.widget.LinearLayout;import android.widget.TextView;
import com.example.medilembrete.data.AppDatabase;import com.example.medilembrete.data.entity.Medicamento;import com.example.medilembrete.data.entity.RegistroDose;import com.example.medilembrete.data.entity.StatusDose;
import java.text.SimpleDateFormat;import java.util.*;
public class HistoricoActivity extends Activity{
 private LinearLayout lista;private Map<Long,Medicamento> meds=new HashMap<>();private List<RegistroDose> registros=new ArrayList<>();
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_historico);lista=findViewById(R.id.listaHistorico);findViewById(R.id.btnVoltarHistorico).setOnClickListener(v->finish());AppDatabase db=AppDatabase.getInstance(this);db.medicamentoDao().listarTodos().observe(this,ms->{meds.clear();if(ms!=null)for(Medicamento m:ms)meds.put(m.getId(),m);render();});db.registroDoseDao().historicoCompleto().observe(this,rs->{registros=rs==null?new ArrayList<>():rs;render();});}
 private void render(){lista.removeAllViews();int tomados=0,perdidos=0;for(RegistroDose r:registros){if(r.getStatus()==StatusDose.TOMADO)tomados++;if(r.getStatus()==StatusDose.PERDIDO)perdidos++;}int total=registros.size(),pct=total==0?0:Math.round(tomados*100f/total);((TextView)findViewById(R.id.txtAdesao)).setText("Adesão ao tratamento\n"+pct+"%  ·  "+tomados+" tomados  ·  "+perdidos+" perdidos");if(total==0){TextView vazio=new TextView(this);vazio.setText("Ainda não existem doses registradas no histórico.");vazio.setTextColor(Color.GRAY);vazio.setPadding(12,28,12,28);lista.addView(vazio);return;}SimpleDateFormat data=new SimpleDateFormat("dd/MM/yyyy",Locale.getDefault()),hora=new SimpleDateFormat("HH:mm",Locale.getDefault());for(RegistroDose r:registros){Medicamento m=meds.get(r.getMedicamentoId());String nome=m==null?"Medicamento":m.getNome();String quando=data.format(new Date(r.getDataHoraProgramada()))+" · "+hora.format(new Date(r.getDataHoraProgramada()));String status=r.getStatus()==StatusDose.TOMADO?"Tomado":r.getStatus()==StatusDose.PERDIDO?"Perdido":"Pendente";TextView item=new TextView(this);item.setText(nome+"\n"+quando+"     "+status);item.setTextColor(r.getStatus()==StatusDose.PERDIDO?Color.rgb(220,38,38):Color.rgb(15,23,42));item.setTextSize(14);item.setPadding(16,16,16,16);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(22);bg.setStroke(1,Color.rgb(226,232,240));item.setBackground(bg);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=10;lista.addView(item,p);}}
}